import type { NBTObject, RootNBT } from 'sandstone/arguments'
import type { MacroArgument } from 'sandstone/core'
import { makeCallable } from 'sandstone/utils'
import * as util from 'util'
import { parseNBT } from './parser'
import { _RawLabelClass } from '../Label'

export abstract class NBTClass {
  abstract [util.inspect.custom]: () => string
}

export class NBTPrimitive extends NBTClass {
  value: number

  unit: string

  constructor(value: number, unit: string) {
    super()
    this.value = value
    this.unit = unit
  }

  /**
   * @internal
   */
  toJSON() {
    return this.value
  }

  [util.inspect.custom] = () => `${this.value}${this.unit}`
}

export type NBTRange = { min?: number, max?: number, leftExclusive?: boolean, rightExclusive?: boolean }

/* oxlint-disable no-unused-vars */

export class NBTLong<Range extends NBTRange = {}> extends NBTPrimitive {
  constructor(value: number) {
    super(value, 'l')
  }
}

export class NBTByte<Range extends NBTRange = {}> extends NBTPrimitive {
  constructor(value: number) {
    super(value, 'b')
  }
}

export class NBTShort<Range extends NBTRange = {}> extends NBTPrimitive {
  constructor(value: number) {
    super(value, 's')
  }
}

export class NBTFloat<Range extends NBTRange = {}> extends NBTPrimitive {
  constructor(value: number) {
    super(value, 'f')
  }
}

export class NBTInt<Range extends NBTRange = {}> extends NBTPrimitive {
  constructor(value: number) {
    super(value, 'i')
  }
}

export class NBTDouble<Range extends NBTRange = {}> extends NBTPrimitive {
  constructor(value: number) {
    super(value, 'd')
  }
}

export class NBTTypedArray extends NBTClass {
  values: number[]

  unit: string

  constructor(values: number[], unit: string) {
    super()
    this.values = values
    this.unit = unit
  }

  /**
   * @internal
   */
  toJSON() {
    return this.values
  }

  [util.inspect.custom] = () => `[${this.unit};${this.values.length === 0 ? '' : this.values.join(',')}]`
}

export class NBTLongArray<Range extends NBTRange = {}> extends NBTTypedArray {
  constructor(values: number[]) {
    super(values, 'L')
  }
}

export class NBTByteArray<Range extends NBTRange = {}> extends NBTTypedArray {
  constructor(values: number[]) {
    super(values, 'B')
  }
}

export class NBTIntArray<Range extends NBTRange = {}> extends NBTTypedArray {
  constructor(values: number[]) {
    super(values, 'I')
  }
}

// type NonEmptyList<Type extends NBTObject> = (
